const xml = $json.data;
const regex = /<text start="[0-9.]+" dur="[0-9.]+">(.*?)</text>/g;
let match;
let transcript = "";

while ((match = regex.exec(xml)) !== null) {
  transcript += match[1].replace(/&#39;/g, "'").replace(/&quot;/g, """).replace(/&amp;/g, "&").replace(/
/g, " ") + " ";
}

return [{ json: { transcript: transcript.trim() } }];

const html = $json.data;
const ytInitialPlayerResponseMatch = html.match(/ytInitialPlayerResponse = ({.*?});/s);

if (ytInitialPlayerResponseMatch && ytInitialPlayerResponseMatch[1]) {
  const playerResponse = JSON.parse(ytInitialPlayerResponseMatch[1]);
  const captionTracks = playerResponse.captions?.playerCaptionsTracklistRenderer?.captionTracks;

  if (captionTracks && captionTracks.length > 0) {
    const englishCaption = captionTracks.find(track => track.languageCode === 'en');
    if (englishCaption) {
      return [{ json: { captionUrl: englishCaption.baseUrl } }];
    } else {
      // Fallback to the first available caption if no English one is found
      return [{ json: { captionUrl: captionTracks[0].baseUrl } }];
    }
  } else {
    throw new Error('No caption tracks found.');
  }
} else {
  throw new Error('Could not extract ytInitialPlayerResponse from HTML.');
}

const url = $json.message.text;
const videoIdMatch = url.match(/(?:youtu\.be/|youtube\.com/(?:watch\?v=|embed/|v/|shorts/))([\w-]{11})/);

if (videoIdMatch && videoIdMatch[1]) {
  return [{ json: { videoId: videoIdMatch[1], originalUrl: url } }];
} else {
  throw new Error('No YouTube video ID found in the message.');
}
